const $=s=>document.querySelector(s);const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const nis=n=>new Intl.NumberFormat('he-IL',{style:'currency',currency:'ILS',maximumFractionDigits:0}).format(n);const date=d=>new Date(d+'T12:00:00').toLocaleDateString('he-IL');
const guests=[{id:1,name:'דניאל ומאיה לוי',group:'המשפחה של נועה',count:2,status:'אישרו',table:3},{id:2,name:'יעל ואור כהן',group:'חברים',count:2,status:'אישרו',table:2},{id:3,name:'משפחת אברהם',group:'המשפחה של איתי',count:4,status:'ממתינים',table:null},{id:4,name:'שירה ישראלי',group:'חברים',count:1,status:'אישרו',table:null},{id:5,name:'רוני ועידו מזרחי',group:'חברים מהעבודה',count:2,status:'אישרו',table:2},{id:6,name:'משפחת פרץ',group:'המשפחה של נועה',count:3,status:'אישרו',table:3},{id:7,name:'עמית גולן',group:'חברים',count:1,status:'לא מגיעים',table:null},{id:8,name:'תמר ויואב הדר',group:'המשפחה של איתי',count:2,status:'ממתינים',table:null}];
const gifts=[{person:1,direction:'received',event:'החתונה של נועה ואיתי',date:'2027-06-18',amount:1200},{person:1,direction:'given',event:'החתונה של דניאל ומאיה',date:'2025-09-04',amount:1000},{person:1,direction:'received',event:'ברית של אורי',date:'2024-03-12',amount:500},{person:2,direction:'received',event:'החתונה של נועה ואיתי',date:'2027-06-18',amount:1000},{person:2,direction:'given',event:'הבריתה של אלה',date:'2026-02-20',amount:600},{person:5,direction:'received',event:'החתונה של נועה ואיתי',date:'2027-06-18',amount:800},{person:6,direction:'received',event:'החתונה של נועה ואיתי',date:'2027-06-18',amount:1500},{person:6,direction:'given',event:'בר המצווה של עומר',date:'2025-05-15',amount:900}];
const rsvpStatuses=['אישרו','מגיעים רק לחופה','ממתינים','לא מגיעים'];let statusFilter='all',statusSort='default';
let current='home',giftFilter='all',query='',selectedTable=3,invitationColor=0;const occupancy=t=>seatingGuests().filter(g=>g.table===t).reduce((n,g)=>n+g.count,0);const initials=name=>esc(name.replace('משפחת ','').split(' ').slice(0,2).map(x=>x[0]).join(''));
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',3200)}
const navigationTrail=[];let renderedEvent=null;
function navigate(view,back=false){if(view==='seating'&&!canAccessSeating()){toast('סידורי ההושבה דורשים אולם מנוי או מסלול אישי עם סקיצה.');return;}if(!back&&view!==current)navigationTrail.push({view:current,event:renderedEvent});if(renderedEvent!==activeEvent){autoSeatUndo=null;autoSeatMessage='';}current=view;query='';renderedEvent=activeEvent;render();$('#back-button').hidden=view==='home';$('#content').scrollTop=0;}
$('#back-button').onclick=()=>{const previous=navigationTrail.pop();if(previous){if(previous.event)activeEvent=previous.event;navigate(previous.view,true);}else navigate('home',true);$('#content').focus({preventScroll:true});};

const metric=(title,value,note,icon)=>`<article class="metric"><div class="metric-head"><span>${title}</span><i>${icon}</i></div><strong>${value}</strong><small>${note}</small></article>`;
function overview(){return `<div class="metrics">${metric('מוזמנים ברשימה','384','168 הזמנות אישיות ומשפחתיות','♧')}${metric('אישרו הגעה','286','74% מהמוזמנים כבר איתכם','✓')}${metric('כבר שובצו','248','נותרו 38 אורחים לשיבוץ','▦')}${metric('השולחנות שלכם','32','באולם סהרה · עד 400 אורחים','◈')}</div><div class="dashboard-grid"><section class="panel"><div class="panel-title"><h2>מי מצטרף לחגיגה?</h2><button class="text-button" data-go="guests">לכל המוזמנים ←</button></div><div class="progress-bar"><span style="width:74%"></span></div><div class="rsvp-legend"><div><strong>286</strong><span><i></i>אישרו הגעה</span></div><div><strong>72</strong><span><i></i>ממתינים לתשובה</span></div><div><strong>26</strong><span><i></i>לא יוכלו להגיע</span></div></div><div class="activity"><h3>עדכונים אחרונים</h3>${[[1,'אישרו הגעה · 2 אורחים','לפני 12 דקות'],[4,'אישרה הגעה · אורחת אחת','לפני שעה'],[5,'שובצו בשולחן 2','לפני שעתיים']].map(([id,detail,time])=>{let p=guests.find(g=>g.id===id);return `<div class="activity-row"><span class="monogram">${initials(p.name)}</span><div>${p.name}<small>${detail}</small></div><time>${time}</time></div>`}).join('')}</div></section><section class="panel"><div class="venue-mini"><span>SAHARA</span></div><div class="panel-title"><h2>כאן זה קורה</h2><button class="text-button" data-go="venue">לאולם שלכם ←</button></div><h3>סהרה · גן ואולם אירועים</h3><p class="venue-description">חלל פתוח, אור טבעי וכל המקום לרגעים שלכם.</p><div class="mini-info"><span>עמק חפר</span><span>עד 400 אורחים</span><span>32 שולחנות</span></div></section></div><div class="next-step"><div><h3>עוד קצת, ולכולם יהיה מקום.</h3><p>38 אורחים אישרו הגעה ומחכים לשולחן שלהם.</p></div><button class="primary" data-go="seating">ממשיכים לסידורי ההושבה</button></div><p class="muted">המספרים והעדכונים במסך זה להמחשת העיצוב בלבד. במסכי העבודה מוצגת רשימת דוגמה מצומצמת.</p>`;}
function guestsView(){return `<div class="toolbar"><div><h2>כל האנשים של האירוע</h2><p>רשימת דוגמה · ${guests.length} משפחות ואורחים</p></div><button class="secondary" data-demo="חיבור אנשי קשר מהטלפון יתווסף בהמשך. לא ניגשנו לאנשי הקשר שלך.">＋ ייבוא אנשי קשר</button></div><input class="search" id="guest-search" aria-label="חיפוש מוזמנים" placeholder="חיפוש לפי שם או קבוצה…" value="${esc(query)}"><div class="rsvp-controls"><label>סינון לפי סטטוס<select id="status-filter"><option value="all">כל הסטטוסים</option>${rsvpStatuses.map(st=>`<option value="${st}" ${statusFilter===st?'selected':''}>${st} (${guests.filter(g=>g.status===st).length})</option>`).join('')}</select></label><label>מיון הרשימה<select id="status-sort"><option value="default" ${statusSort==='default'?'selected':''}>סדר מקורי</option><option value="status" ${statusSort==='status'?'selected':''}>לפי סטטוס אישור</option><option value="name" ${statusSort==='name'?'selected':''}>לפי שם</option></select></label></div><div class="table-wrap"><table><thead><tr><th>שם האורח / המשפחה</th><th>קבוצה / צד (לא חובה)</th><th>אורחים</th><th>אישור הגעה</th><th>שולחן</th><th></th></tr></thead><tbody>${guests.filter(g=>(g.name+g.group).includes(query)&&(statusFilter==='all'||g.status===statusFilter)).sort((a,b)=>statusSort==='status'?rsvpStatuses.indexOf(a.status)-rsvpStatuses.indexOf(b.status):statusSort==='name'?a.name.localeCompare(b.name,'he'):0).map(g=>`<tr><td><div class="guest-name"><span class="monogram">${initials(g.name)}</span><button class="name-button" data-person="${g.id}">${g.name}</button></div></td><td><span class="guest-group">${esc(g.group)}</span><select class="guest-side" data-side="${g.id}" aria-label="הצד של ${esc(g.name)} (לא חובה)">${['','הצד של נועה','הצד של איתי','משותף'].map(side=>`<option value="${side}" ${(g.side||'')===side?'selected':''}>${side||'ללא ציון צד'}</option>`).join('')}</select></td><td>${g.count}</td><td><select class="rsvp-status ${g.status==='מגיעים רק לחופה'?'ceremony':''}" data-rsvp="${g.id}" aria-label="סטטוס אישור עבור ${esc(g.name)}">${rsvpStatuses.map(st=>`<option ${st===g.status?'selected':''}>${st}</option>`).join('')}</select></td><td>${g.table||'טרם שובצו'}</td><td><button class="text-button" data-person="${g.id}">כרטיס אורח</button></td></tr>`).join('')||'<tr><td colspan="6">לא נמצאו מוזמנים התואמים לחיפוש.</td></tr>'}</tbody></table></div>`;}
function giftsView(){const sum=d=>gifts.filter(g=>g.direction===d).reduce((n,g)=>n+g.amount,0);const filtered=gifts.filter(g=>(giftFilter==='all'||g.direction===giftFilter)&&giftContact(g.person).name.includes(query));return `<div class="toolbar"><div><h2>יומן המתנות</h2><p>מה קיבלנו מהם, ומה נתנו להם. כל ההיסטוריה נשמרת יחד.</p></div><button class="primary" id="add-gift">＋ רישום מתנה</button></div><div class="gift-summary"><div><span>מתנות שקיבלנו · בכל האירועים</span><strong><bdi>${nis(sum('received'))}</bdi></strong></div><div><span>מתנות שנתנו בכל האירועים</span><strong><bdi>${nis(sum('given'))}</bdi></strong></div></div><input class="search" id="gift-search" placeholder="חיפוש איש קשר…" aria-label="חיפוש איש קשר" value="${esc(query)}"><div class="tabs">${[['all','כל המתנות'],['received','קיבלנו מהם'],['given','נתנו להם']].map(([v,t])=>`<button data-filter="${v}" class="${giftFilter===v?'selected':''}" aria-pressed="${giftFilter===v}">${t}</button>`).join('')}</div><div class="table-wrap"><table><thead><tr><th>איש קשר</th><th>כיוון המתנה</th><th>האירוע</th><th>תאריך</th><th>סכום</th></tr></thead><tbody>${filtered.map(g=>`<tr><td><button class="name-button" data-person="${g.person}">${esc(giftContact(g.person).name)}</button></td><td><span class="${g.direction}">${g.direction==='received'?'קיבלנו מהם':'נתנו להם'}</span></td><td>${esc(g.event)}</td><td><bdi>${date(g.date)}</bdi></td><td class="gift-cell"><bdi>${nis(g.amount)}</bdi></td></tr>`).join('')||'<tr><td colspan="5">אין מתנות להצגה. אפשר לרשום מתנה חדשה.</td></tr>'}</tbody></table></div><p class="muted">נתוני הדגמה בלבד, לרבות מתנות באירוע העתידי. לחיצה על שם מציגה היסטוריה בשני הכיוונים.</p>`;}

let seatingFilter='all',autoSeatUndo=null,autoSeatMessage='';
function fillOpenSeats(){if(!canAssignSeating())return;autoSeatUndo=seatingGuests().map(g=>({id:g.id,table:g.table}));const waiting=seatingGuests().filter(g=>g.flexible&&g.status==='אישרו'&&!g.table).sort((a,b)=>b.count-a.count);let placed=0;for(const g of waiting){const choices=Object.keys(seatingCapacities()).map(Number).filter(t=>seatingCapacities()[t]-occupancy(t)>=g.count).sort((a,b)=>{const usedA=occupancy(a)>0,usedB=occupancy(b)>0;return Number(usedB)-Number(usedA)||(seatingCapacities()[a]-occupancy(a))-(seatingCapacities()[b]-occupancy(b));});if(choices.length){g.table=choices[0];placed+=g.count;}}const remaining=waiting.filter(g=>!g.table).reduce((n,g)=>n+g.count,0);autoSeatMessage=waiting.length?`שובצו ${placed} אורחים ללא העדפת הושבה.${remaining?' '+remaining+' נשארו ללא מקום מתאים בלי לפצל משפחה.':''}`:'אין כרגע אורחים שאישרו, לא שובצו וסומנו ללא העדפת הושבה.';if(!placed)autoSeatUndo=null;render();toast(autoSeatMessage);}

function seating(){const unseated=seatingGuests().filter(g=>g.status==='אישרו'&&!g.table);const list=seatingFilter==='unseated'?unseated:seatingGuests();return `<div class="toolbar"><div><h2>לכל אחד יש מקום</h2><p>כל המוזמנים והשולחנות שלהם, לצד המאשרים שעוד מחכים למקום.</p></div><button class="secondary" data-demo="זו תצוגת הודעה בלבד. במוצר המלא יישלח לכל אורח מספר שולחן ומפה מסומנת, לאחר אישור שלך.">תצוגת הודעת הושבה</button></div><div class="auto-seat-panel"><div><h3>ממלאים את המקומות הפנויים</h3><p>סמנו למי אין העדפת הושבה. נשלים קודם שולחנות שכבר מאוכלסים, בלי לפצל זוגות או משפחות ובלי להזיז אורחים ששובצו.</p><small>שיוך לצד הוא מידע בלבד; סימון ללא העדפה מאפשר שיבוץ בכל שולחן.</small></div><button class="primary" id="auto-seat">מילוי מקומות פנויים</button>${autoSeatUndo?'<button class="secondary" id="undo-auto-seat">ביטול השיבוץ האוטומטי</button>':''}</div>${autoSeatMessage?`<p class="auto-seat-result" role="status">${esc(autoSeatMessage)}</p>`:''}<div class="seating-layout"><div><div class="seating-key"><span><i class="chair-key occupied"></i>כיסא תפוס</span><span><i class="chair-key"></i>כיסא פנוי</span><span>${Object.keys(seatingCapacities()).reduce((n,t)=>n+seatingCapacities()[t]-occupancy(Number(t)),0)} מקומות פנויים במפת הדוגמה</span></div><div class="floor-wrap"><div class="floor"><div class="stage">במה וחופה</div><div class="tables">${Object.keys(seatingCapacities()).map(Number).slice(0,Math.ceil(Object.keys(seatingCapacities()).length/2)).map(tableButton).join('')}</div><div class="dance">רחבת הריקודים</div><div class="tables">${Object.keys(seatingCapacities()).map(Number).slice(Math.ceil(Object.keys(seatingCapacities()).length/2)).map(tableButton).join('')}</div></div></div><p class="floor-note">לחיצה על שולחן פותחת את רשימת היושבים ואפשרויות הוספה והסרה. מיקום הכיסאות להמחשה; אין עדיין שיוך לאדם בכיסא מסוים.</p><p class="floor-note">מפת שיבוץ סכמטית. השיבוצים נשמרים עד לרענון.</p></div><section class="panel seating-roster"><h3>רשימת המוזמנים</h3><div class="seating-tabs"><button data-seating-filter="all" aria-pressed="${seatingFilter==='all'}" class="${seatingFilter==='all'?'selected':''}">כולם <b>${seatingGuests().length}</b></button><button data-seating-filter="unseated" aria-pressed="${seatingFilter==='unseated'}" class="${seatingFilter==='unseated'?'selected':''}">אישרו ולא שובצו <b>${unseated.reduce((n,g)=>n+g.count,0)}</b></button></div><p class="muted">${seatingFilter==='all'?'כל הסטטוסים מוצגים. שיבוץ לארוחה זמין למי שאישרו הגעה.':unseated.length+' רשומות ממתינות לשיבוץ · אפשר לבחור שולחן לצד כל שם.'}</p><div class="seat-list">${list.map(g=>`<div class="seat-guest"><div><bdi>${esc(g.name)}</bdi><small>${g.count===1?'אורח אחד':g.count+' אורחים'} · ${esc(g.status)}</small><small class="guest-side-note">${esc(g.side||'ללא ציון צד')}</small>${g.status==='אישרו'?`<label class="flexible-label"><input type="checkbox" data-flexible="${g.id}" ${g.flexible?'checked':''}> אין העדפת הושבה</label>`:''}<span class="seat-location">${g.table?'שובץ · שולחן '+g.table:g.status==='אישרו'?'ממתינים לשיבוץ':g.status==='מגיעים רק לחופה'?'ללא הושבה לארוחה':'ללא שולחן'}</span></div>${g.status==='אישרו'?`<select data-seat="${g.id}" aria-label="שולחן עבור ${esc(g.name)}"><option value="">ללא שולחן</option>${Object.keys(seatingCapacities()).map(t=>`<option value="${t}" ${g.table===Number(t)?'selected':''}>שולחן ${t}</option>`).join('')}</select>`:'<span class="seat-ineligible">—</span>'}</div>`).join('')||'<div class="seating-empty">כולם כבר מצאו מקום.<small>אין כרגע מאשרי הגעה שממתינים לשיבוץ.</small></div>'}</div></section></div>`;}
function tableButton(t){const taken=occupancy(t),capacity=seatingCapacities()[t];return `<button class="round-table ${selectedTable===t?'selected':''}" data-table="${t}" aria-label="שולחן ${t}, ${taken} מתוך ${capacity} מקומות, ${capacity-taken} פנויים" aria-pressed="${selectedTable===t}">${Array.from({length:capacity},(_,i)=>{const a=(i/capacity)*Math.PI*2;return `<span aria-hidden="true" class="table-chair ${i<taken?'occupied':''}" style="left:${50+Math.cos(a)*61}%;top:${50+Math.sin(a)*61}%;transform:translate(-50%,-50%) rotate(${i/capacity*360+90}deg)"></span>`}).join('')}<strong>${t}</strong><small><bdi>${taken} / ${capacity}</bdi></small><span class="table-vacancy">${capacity-taken} פנויים</span></button>`;}
const tableDialog=document.createElement('dialog');tableDialog.id='table-dialog';tableDialog.setAttribute('aria-label','ניהול אורחים בשולחן');document.body.appendChild(tableDialog);
function openTable(t){if(!canAssignSeating())return;selectedTable=t;render();drawTableDialog();if(!tableDialog.open)tableDialog.showModal();}
function drawTableDialog(){const seated=seatingGuests().filter(g=>g.table===selectedTable),available=seatingGuests().filter(g=>!g.table&&g.status==='אישרו');const remaining=seatingCapacities()[selectedTable]-occupancy(selectedTable);tableDialog.innerHTML=`<div class="dialog-top"><div><h2>האורחים בשולחן ${selectedTable}</h2><p class="muted">${occupancy(selectedTable)} מתוך ${seatingCapacities()[selectedTable]} מקומות · ${remaining} מקומות פנויים</p></div><button class="close" aria-label="סגירה">×</button></div><h3>יושבים בשולחן</h3><div class="table-dialog-list">${seated.map(g=>`<div class="table-person"><div><bdi>${esc(g.name)}</bdi><small>${g.count} מקומות · ${esc(g.group)}</small></div><button class="secondary" data-unseat="${g.id}">הסרה מהשולחן</button></div>`).join('')||'<p class="muted">השולחן עדיין פנוי. הוסיפו אורחים מהרשימה למטה.</p>'}</div><div class="table-dialog-add"><h3>הוספה מרשימת המוזמנים</h3><p class="muted">מוצגים רק מוזמנים שאישרו וטרם שובצו. להעברת מוזמן שכבר שובץ, שנו את מספר השולחן ברשימת המוזמנים.</p><label class="table-search-label">חיפוש אורח<input id="table-guest-search" type="search" placeholder="שם אורח או משפחה…"></label><div id="available-table-guests" class="table-dialog-list">${available.map(g=>`<div class="table-person" data-candidate-name="${esc(g.name)}"><div><bdi>${esc(g.name)}</bdi><small>${g.count} מקומות · ${g.table?'בשולחן '+g.table:'ללא שולחן'}</small></div><button class="${g.count>remaining?'secondary':'primary'}" data-seat-add="${g.id}" ${g.count>remaining?'disabled':''}>${g.count>remaining?'אין מספיק מקום':g.table?'העברה לכאן':'הוספה לשולחן'}</button></div>`).join('')||'<p class="muted">אין מוזמנים שאישרו וממתינים לשיבוץ.</p>'}</div><p id="table-no-matches" class="muted" hidden>לא נמצאו אורחים התואמים לחיפוש.</p></div><p class="muted">הסרה משולחן אינה מוחקת את האורח מרשימת המוזמנים. השינויים להדגמה בלבד ונמחקים ברענון.</p>`;}
tableDialog.addEventListener('click',e=>{if(!canAssignSeating())return;const b=e.target.closest('button');if(!b)return;if(b.dataset.unseat||b.dataset.seatAdd){autoSeatUndo=null;autoSeatMessage='';}if(b.dataset.unseat){seatingGuests().find(g=>g.id===Number(b.dataset.unseat)).table=null;render();drawTableDialog();toast('האורח הוסר מהשולחן ונשאר ברשימת המוזמנים');}if(b.dataset.seatAdd){const g=seatingGuests().find(g=>g.id===Number(b.dataset.seatAdd));if(!g||g.status!=='אישרו')return;if(g.table){drawTableDialog();toast('המוזמן כבר שובץ לשולחן '+g.table);return;}if(g.count+occupancy(selectedTable)>seatingCapacities()[selectedTable]){toast('אין מספיק מקומות בשולחן');return;}g.table=selectedTable;render();drawTableDialog();toast(g.name+' שובץ לשולחן '+selectedTable);}});
tableDialog.addEventListener('input',e=>{if(e.target.id!=='table-guest-search')return;let visible=0;tableDialog.querySelectorAll('[data-candidate-name]').forEach(row=>{row.hidden=!row.dataset.candidateName.includes(e.target.value.trim());if(!row.hidden)visible++;});$('#table-no-matches').hidden=visible>0;});
const invitationLocations={};
const invitationVenueAddresses={sahara:'עמק חפר — כתובת מדויקת טרם הוזנה', 'demo-center':'רחוב הדוגמה 10, עיר לדוגמה · כתובת להמחשה בלבד'};
const invitationHeadings={};const defaultInvitationHeading='TOGETHER WITH OUR FAMILIES';
const invitationMessages={};const defaultInvitationMessage='שמחים להזמין אתכם לחגוג איתנו\nאת היום הכי מרגש שלנו';
function invitationMessage(){return invitationMessages[activeEvent]??defaultInvitationMessage;}
function invitations(){return `<div class="toolbar"><div><h2>הרגע שלכם, ההזמנה שלכם</h2><p>בחרו גוון וצפו בתצוגה מקדימה של ההזמנה.</p></div></div><div class="invitation-layout"><div class="invitation" style="background:${['#ece2d2','#e3e6dc','#f0e1df','#f2e4bc','#e0e8ee'][invitationColor]}"><span class="latin" id="invitation-heading-preview" dir="auto">${esc(invitationHeadings[activeEvent]??defaultInvitationHeading)}</span><h2>נועה ואיתי</h2><p id="invitation-message-preview" class="invitation-message">${esc(invitationMessage())}</p><p style="margin-top:22px"><bdi>18.06.2027</bdi><br><span id="invitation-venue-name-preview">${esc(invitationLocationDetails().name)}</span><br><span id="invitation-venue-address-preview">${esc(invitationLocationDetails().address)}</span><br>קבלת פנים בשעה 19:30</p><button class="primary" data-demo="כאן האורח יבחר אם יגיע וכמה אנשים יצטרפו. זהו אבטיפוס עיצוב, ללא שליחת תשובה.">אישור הגעה</button></div><section class="panel"><h2>הפרטים הקטנים, הטאץ׳ האישי</h2>${invitationVenueEditor()}<label class="invitation-message-label" for="invitation-heading">המשפט העליון בהזמנה</label><input id="invitation-heading" type="text" dir="auto" maxlength="100" value="${esc(invitationHeadings[activeEvent]??defaultInvitationHeading)}" aria-describedby="invitation-heading-help"><p class="muted" id="invitation-heading-help">אפשר לכתוב בעברית או באנגלית, או להשאיר ריק כדי להסתיר.</p><button type="button" class="text-button" id="reset-invitation-heading">חזרה למשפט העליון המקורי</button><label class="invitation-message-label" for="invitation-message">המשפט שלכם להזמנה</label><textarea id="invitation-message" rows="4" maxlength="350" aria-describedby="invitation-message-help">${esc(invitationMessage())}</textarea><p class="muted" id="invitation-message-help">כתבו את הנוסח שמתאים לכם. התצוגה מתעדכנת מיד, והשינוי נשמר באירוע עד לרענון.</p><button type="button" class="text-button" id="reset-invitation-message">חזרה לנוסח המקורי</button><span class="form-label">פלטת ההזמנה</span><div class="swatches">${['חול מדברי','מרווה עדינה','ורוד עתיק','שמפניה מוזהבת','כחול פנינה'].map((c,i)=>`<button data-color="${i}" class="${i===invitationColor?'selected':''}" aria-label="${c}" aria-pressed="${i===invitationColor}"></button>`).join('')}</div><div class="design-note">ההזמנה בוואטסאפ תכלול קישור אישי לאישור הגעה. לאחר השיבוץ, תישלח הודעה נוספת עם מספר השולחן ומפה שמסמנת אותו.</div><button class="primary" data-demo="תצוגה בלבד: לא נשלחה הודעת וואטסאפ לאיש.">תצוגת שליחה בוואטסאפ</button><p class="muted">אפשר לערוך את משפט ההזמנה כאן. חיבור וואטסאפ ושליחה בפועל יפותחו בהמשך.</p></section></div>`;}
function venue(){return `<div class="toolbar"><div><h2>סהרה · גן ואולם אירועים</h2><p>עמוד אולם לדוגמה · כל הפרטים לפני שמתחילים לשבץ.</p></div></div><div class="venue-grid"><div><div class="venue-hero">SAHARA</div><p class="muted">איור להמחשת העיצוב. תמונות אמיתיות של האולם יופיעו כאן בהמשך.</p></div><section class="panel"><h2>מרחב לרגעים גדולים</h2><p>גן פתוח לקבלת הפנים ואולם בגוונים טבעיים. המקום שבו כל האנשים שלכם נפגשים סביב אותו רגע.</p><div class="venue-features"><span>עד 400 אורחים</span><span>32 שולחנות</span><span>גן לקבלת פנים</span><span>גישה נגישה</span><span>חניה במקום</span></div><div class="design-note">בעל האולם יעביר סקיצה עם שולחנות וכיסאות. בעל האירוע ישבץ את האורחים על גבי המפה המאושרת.</div><button class="primary" data-go="seating">למפת ההושבה</button><p class="muted">ניהול מנוי חודשי והעלאת סקיצה לאולם יתווספו באזור נפרד למנהלי אולמות.</p></section></div>`;}
function render(){const openDetails=[...document.querySelectorAll('details[open][id]')].map(detail=>detail.id);updateShell();const focused=document.activeElement?.id;const start=document.activeElement?.selectionStart;$('#content').innerHTML=({seatingPurchase:paidSeatingView,venues:venuesView,providers:providersView,home:homeView,events:eventsView,newEvent:newEventView,eventGifts:eventGiftsView,expenses:expensesView,overview:activeOverview,guests:eventGuestView,gifts:giftsView,seating:eventSeatingView,invitations:eventInvitationView,venue}[current])();document.querySelectorAll('[data-go="seating"]').forEach(button=>{button.disabled=!canAccessSeating();button.title=button.disabled?'נדרש אולם מנוי או מסלול אישי עם סקיצה':'';if(button.disabled)button.setAttribute('aria-label','סידורי הושבה — נדרש מנוי אולם או מסלול אישי');});openDetails.forEach(id=>{const detail=document.getElementById(id);if(detail)detail.open=true;});if(focused&&document.getElementById(focused)){document.getElementById(focused).focus();if(start!==null&&start!==undefined)document.getElementById(focused).setSelectionRange(start,start);}}
function person(id){const p=giftContact(id);$('#person-content').innerHTML=`<div class="dialog-top"><div class="contact-title"><span class="monogram">${initials(p.name)}</span><div><h2>${esc(p.name)}</h2><small>${p.group} · איש קשר משפחתי</small></div></div><button class="close" aria-label="סגירה">×</button></div><p class="muted">המתנות שלנו לאורך השנים</p><div class="contact-history">${gifts.filter(g=>g.person===id).sort((a,b)=>b.date.localeCompare(a.date)).map(g=>`<div class="history-row"><div><b>${esc(g.event)}</b><small><bdi>${date(g.date)}</bdi> · ${g.direction==='received'?'קיבלנו מהם':'נתנו להם'}</small></div><b class="${g.direction}"><bdi>${nis(g.amount)}</bdi></b></div>`).join('')||'<p class="muted">עדיין אין מתנות רשומות לאיש הקשר הזה.</p>'}</div><button class="primary" style="margin-top:22px" id="person-add" data-id="${id}">＋ רישום מתנה לאיש הקשר</button>`;$('#person-dialog').showModal();}
let giftEventContext=null;
function giftContact(id){return guests.find(g=>g.id===id)||Object.values(eventGuestLists).flat().find(g=>g.id===id)||{name:'איש קשר',group:''};}
function eventGiftsView(){const list=gifts.filter(g=>g.eventId===activeEvent||(!g.eventId&&g.event===active().name&&g.date===active().date&&g.direction==='received'));return `<div class="toolbar"><div><h2>מתנות</h2><p>המתנות שהתקבלו באירוע הזה מופיעות אוטומטית גם ביומן המתנות האישי.</p></div><button class="primary" id="add-event-gift">＋ רישום מתנה לאירוע</button></div><div class="gift-summary"><div><span>סך המתנות באירוע</span><strong><bdi>${nis(list.reduce((n,g)=>n+g.amount,0))}</bdi></strong></div><div><span>מתנות שנרשמו</span><strong>${list.length}</strong></div></div><div class="table-wrap"><table><thead><tr><th>ממי קיבלנו</th><th>סכום</th><th>האירוע</th><th>תאריך</th></tr></thead><tbody>${list.map(g=>`<tr><td><button class="name-button" data-person="${g.person}">${esc(giftContact(g.person).name)}</button></td><td><bdi>${nis(g.amount)}</bdi></td><td>${esc(g.event)}</td><td><bdi>${date(g.date)}</bdi></td></tr>`).join('')||'<tr><td colspan="4">עדיין אין מתנות באירוע. הוסיפו מתנה כדי להתחיל.</td></tr>'}</tbody></table></div><button class="text-button" data-go="gifts">לכל ההיסטוריה ביומן המתנות ←</button><p class="muted">העדכון משותף לשני המסכים בזיכרון ההדגמה בלבד. הנתונים מתאפסים ברענון.</p>`;}
let giftContacts=[];
const normalizeGuestName=value=>String(value).normalize('NFKC').trim().replace(/\s+/g,' ').toLocaleLowerCase('he');
function renderGiftContacts(){const search=normalizeGuestName($('#gift-contact-search').value);const matches=giftContacts.filter(g=>normalizeGuestName(g.name).includes(search));$('#gift-contact-results').innerHTML=matches.map(g=>`<button type="button" class="gift-contact-option" data-gift-contact="${g.id}" aria-pressed="${String(g.id)===$('#gift-person').value}"><span>${esc(g.name)}</span><small>${esc(g.group||g.side||'מוזמן ברשימה')}</small></button>`).join('');$('#gift-contact-status').textContent=!giftContacts.length?'אין עדיין מוזמנים באירוע הזה. לאחר הוספת מוזמנים תוכלו לחפש ולרשום עבורם מתנה.':!matches.length?'לא נמצאו מוזמנים בשם הזה. נסו שם אחר.':$('#gift-person').value?'המוזמן נבחר. אפשר להזין את פרטי המתנה.':'בחרו מוזמן מתוצאות החיפוש.';$('#gift-form button[type=submit]').disabled=!$('#gift-person').value;}
function addGift(id,eventScope=false){giftEventContext=eventScope?activeEvent:null;$('#person-dialog').close();$('#gift-form').reset();giftContacts=eventScope?(activeEvent==='wedding'?guests:eventGuestLists[activeEvent]||[]):[...guests,...Object.values(eventGuestLists).flat()];const selected=giftContacts.find(g=>String(g.id)===String(id));$('#gift-person').value=selected?String(selected.id):'';$('#gift-contact-search').value=selected?selected.name:'';renderGiftContacts();$('#gift-form [name=date]').value=eventScope?active().date:'2027-06-18';$('#gift-form [name=event]').value=eventScope?active().name:'';$('#gift-form [name=date]').readOnly=eventScope;$('#gift-form [name=event]').readOnly=eventScope;$('#gift-form .segmented').hidden=eventScope;$('#gift-dialog').showModal();$('#gift-contact-search').focus();}
document.addEventListener('input',e=>{if(e.target.id!=='gift-contact-search')return;$('#gift-person').value='';renderGiftContacts();});
document.addEventListener('click',e=>{const button=e.target.closest('[data-gift-contact]');if(!button)return;const selected=giftContacts.find(g=>String(g.id)===button.dataset.giftContact);if(!selected)return;$('#gift-person').value=String(selected.id);$('#gift-contact-search').value=selected.name;renderGiftContacts();$('#gift-form [name=amount]').focus();});

document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.id==='auto-seat')fillOpenSeats();if(b.id==='undo-auto-seat'&&autoSeatUndo&&canAssignSeating()){autoSeatUndo.forEach(old=>seatingGuests().find(g=>g.id===old.id).table=old.table);autoSeatUndo=null;autoSeatMessage='השיבוץ האוטומטי בוטל.';render();}if(b.dataset.seatingFilter){seatingFilter=b.dataset.seatingFilter;render();}if(b.dataset.view)navigate(b.dataset.view);if(b.dataset.go)navigate(b.dataset.go);if(b.dataset.person)person(Number(b.dataset.person));if(b.classList.contains('close'))b.closest('dialog').close();if(b.dataset.demo)toast(b.dataset.demo);if(b.dataset.filter){giftFilter=b.dataset.filter;render();}if(b.dataset.table){openTable(Number(b.dataset.table));}if(b.dataset.color){invitationColor=Number(b.dataset.color);render();}if(b.id==='add-event-gift')addGift(null,true);if(b.id==='add-gift')addGift();if(b.id==='person-add')addGift(b.dataset.id);});
document.addEventListener('input',e=>{if(e.target.id==='guest-search'||e.target.id==='gift-search'){query=e.target.value;render();}});
document.addEventListener('change',e=>{if(e.target.dataset.side){guests.find(g=>g.id===Number(e.target.dataset.side)).side=e.target.value;render();}if(e.target.dataset.flexible){if(!canAssignSeating())return;seatingGuests().find(g=>g.id===Number(e.target.dataset.flexible)).flexible=e.target.checked;render();}if(e.target.id==='status-filter'){statusFilter=e.target.value;render();}if(e.target.id==='status-sort'){statusSort=e.target.value;render();}if(e.target.dataset.rsvp){autoSeatUndo=null;autoSeatMessage='';const g=guests.find(p=>p.id===Number(e.target.dataset.rsvp));g.status=e.target.value;const hadTable=g.table;if(g.status!=='אישרו')g.table=null;render();toast(hadTable&&g.status!=='אישרו'?'הסטטוס עודכן והשולחן פונה. אורחי חופה בלבד אינם משובצים לארוחה.':'סטטוס האישור עודכן בתצוגת הדוגמה');}if(e.target.dataset.seat){if(!canAssignSeating())return;autoSeatUndo=null;autoSeatMessage='';const p=seatingGuests().find(g=>g.id===Number(e.target.dataset.seat));const t=Number(e.target.value)||null;const existing=p.table===t?p.count:0;if(t&&occupancy(t)-existing+p.count>seatingCapacities()[t]){toast('אין מספיק מקומות בשולחן הזה. בחרו שולחן אחר.');render();return;}p.table=t;selectedTable=t||selectedTable;render();toast('השיבוץ עודכן בתצוגת הדוגמה');}});
$('#gift-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);const context=giftEventContext?myEvents.find(ev=>ev.id===giftEventContext):null;const personId=Number(f.get('person'));if(!giftContacts.some(g=>g.id===personId)){toast('בחרו מוזמן מתוצאות החיפוש לפני שמירת המתנה');return;}const event=context?context.name:f.get('event').trim();const amount=Number(f.get('amount'));if(!event||!Number.isFinite(amount)||amount<=0)return;gifts.push({person:Number(f.get('person')),direction:context?'received':f.get('direction'),event,date:context?context.date:f.get('date'),amount,...(context?{eventId:context.id}:{})});$('#gift-dialog').close();navigate(context?'eventGifts':'gifts');toast(context?'המתנה נשמרה באירוע ועודכנה ביומן המתנות':'המתנה נוספה לתצוגת הדוגמה');};const myEvents=[{id:'wedding',name:'החתונה של נועה ואיתי',date:'2027-06-18',type:'חתונה',past:false},{id:'brit',name:'ברית של אורי',date:'2024-03-12',type:'ברית',past:true}];let activeEvent='wedding';
const expenseRecords=[{id:1,event:'wedding',supplier:'אולם סהרה',category:'אולם וקייטרינג',total:96000,payments:[{amount:15000,date:'2026-10-20'}]},{id:2,event:'wedding',supplier:'סטודיו אור',category:'צילום',total:12500,payments:[{amount:2500,date:'2026-10-22'}]},{id:3,event:'wedding',supplier:'די־ג׳יי רותם',category:'מוזיקה',total:8000,payments:[]},{id:4,event:'wedding',supplier:'פרחים במדבר',category:'עיצוב ופרחים',total:6500,payments:[{amount:6500,date:'2026-10-25'}]}];
const active=()=>myEvents.find(e=>e.id===activeEvent);const paid=r=>r.payments.reduce((n,p)=>n+p.amount,0);let expenseId=5;
function updateShell(){const general=['home','events','newEvent','gifts','providers','venues'].includes(current);$('.event-title').hidden=general;$('.countdown').hidden=activeEvent!=='wedding';$('.crumb').textContent=general?({home:'המרחב האישי שלי',events:'האירועים שלי',newEvent:'הקמת אירוע חדש',gifts:'יומן המתנות',providers:'בעלי מקצוע',venues:'אולמות אירועים'}[current]):'האירועים שלי / '+active().name;if(!general){$('.event-home-button').textContent=active().name;$('.event-home-button').setAttribute('aria-label','לדף הראשי של האירוע '+active().name);$('.event-title p').textContent=date(active().date)+' · '+active().type;}document.querySelectorAll('.rail nav [data-view]').forEach(b=>{b.hidden=(general&&!['home','events','gifts','providers'].includes(b.dataset.view));});}
function homeView(){return `<div class="home-heading"><span class="kicker">BESTEVENT · המרחב שלכם</span><h1>נהנים מרגעים מיוחדים</h1><p>מה תרצו לעשות היום?</p></div><div class="home-actions"><button data-go="newEvent"><span class="home-symbol">＋</span><h2>הקמת אירוע חדש</h2><p>מתחילים לתכנן את הרגע הבא שלכם</p><span class="home-link">יצירת אירוע ←</span></button><button data-go="events"><span class="home-symbol">▤</span><h2>האירועים שלי</h2><p>אירועים קרובים וגם אלו שכבר חגגתם</p><span class="home-link">לכל האירועים ←</span></button><button data-go="gifts"><span class="home-symbol"><svg class="gift-box-icon" viewBox="0 0 40 40" fill="none" aria-hidden="true"><path d="M7 19h26v16H7z" fill="#e6cc85" stroke="currentColor" stroke-width="1.4"/><path d="M5 13h30v7H5z" fill="#f6e7bc" stroke="currentColor" stroke-width="1.4"/><path d="M17 13h6v22h-6z" fill="#b48b31"/><path d="M20 13c-4-1-11-1-11-6 0-2 2-3 4-2 4 1 7 8 7 8Zm0 0c4-1 11-1 11-6 0-2-2-3-4-2-4 1-7 8-7 8Z" fill="#edda9f" stroke="currentColor" stroke-width="1.4" stroke-linejoin="round"/><path d="m20 13-6 10m6-10 6 10" stroke="#82621f" stroke-width="1.4" stroke-linecap="round"/></svg></span><h2>יומן המתנות</h2><p>מה קיבלנו ומה נתנו, בלי לפתוח אירוע</p><span class="home-link">ליומן המתנות ←</span></button><button data-go="venues"><span class="home-symbol"><svg viewBox="0 0 40 40" width="34" height="34" fill="none" aria-hidden="true"><path d="M5 35h30M8 35V15l12-9 12 9v20M5 15h30M16 35V24a4 4 0 0 1 8 0v11M12 19v6m16-6v6M20 2v4" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/></svg></span><h2>אולמות אירועים</h2><p>מוצאים את המקום לרגע המיוחד שלכם</p><span class="home-link">למאגר האולמות ←</span></button><button data-go="providers"><span class="home-symbol">✧</span><h2>בעלי מקצוע</h2><p>מוצאים את האנשים הנכונים לאירוע שלכם</p><span class="home-link">למאגר בעלי המקצוע ←</span></button></div><div class="design-note">תצוגת עיצוב מקומית · הנתונים לדוגמה. אירועים, מתנות ותשלומים שנוספים כאן נשמרים עד לרענון בלבד.</div>`;}
function eventsView(){return `<div class="toolbar"><div><h2>האירועים שלי</h2><p>כל החגיגות שלכם, הקרובות והקודמות.</p></div><button class="primary" data-go="newEvent">＋ הקמת אירוע חדש</button></div>${[false,true].map(past=>`<h3 class="event-group-title">${past?'אירועים שכבר היו':'האירועים הקרובים'}</h3><div class="personal-events">${myEvents.filter(e=>e.past===past).map(e=>`<button class="personal-event" data-open-event="${e.id}"><span class="home-symbol">${past?'✧':'◈'}</span><div><h3>${esc(e.name)}</h3><small><bdi>${date(e.date)}</bdi> · ${esc(e.type)}</small></div><span class="home-link">פתיחת האירוע ←</span></button>`).join('')||'<p class="muted">אין אירועים להצגה.</p>'}</div>`).join('')}`;}
function newEventView(){return `<div class="toolbar"><div><h2>מתחילים אירוע חדש</h2><p>כמה פרטים קטנים, ומתחילים לתכנן.</p></div></div><form id="new-personal-event" class="panel event-create"><label>שם האירוע<input name="name" required maxlength="90" placeholder="למשל, בר המצווה של עומר"></label><div class="form-grid"><label>סוג האירוע<select name="type"><option>חתונה</option><option>בר מצווה</option><option>בת מצווה</option><option>ברית</option><option>בריתה</option><option>יום הולדת</option><option>אחר</option></select></label><label>תאריך<input type="date" name="date" required></label></div><p class="muted">אירוע לדוגמה יתווסף לרשימה, וניתן יהיה לנהל בו הוצאות בנפרד.</p><button class="primary" type="submit">יצירת האירוע</button></form>`;}

const eventGuestLists={};
function activeOverview(){return paidSeatingOffer()+`<div class="toolbar"><div><h2>מתכננים את ${esc(active().name)}</h2><p>מתחילים בהזמנה, מוסיפים את האנשים שלכם וממשיכים לכל פרטי האירוע.</p></div></div><div class="event-steps">${[['invitations','1','מעצבים את ההזמנה','בוחרים עיצוב וממלאים את פרטי האירוע'],['guests','2','בונים רשימת מוזמנים','מוסיפים אורחים ידנית או דרך אנשי קשר'],['guests','3','שולחים ועוקבים','הזמנה לכולם ומעקב אחר אישורי ההגעה']].map(([view,n,title,note])=>`<button data-go="${view}"><span class="step-number">${n}</span><div><h3>${title}</h3><p>${note}</p></div><span>←</span></button>`).join('')}</div><h3 class="event-group-title">כל מה שצריך לאירוע</h3><div class="event-tools">${[['seating','▦','סידורי הושבה','שולחנות, שיבוץ ומקומות פנויים'],['eventGifts','◇','מתנות','רישום מתנות שהתקבלו באירוע'],['expenses','₪','הוצאות ותשלומים','בעלי מקצוע, תשלומים ויתרות'],['venue','⌂','האולם שלנו','פרטים ומפת האולם']].map(([view,icon,title,note])=>`<button data-go="${view}"><span>${icon}</span><h3>${title}</h3><p>${note}</p></button>`).join('')}</div>`;}
function eventInvitationView(){return '<div class="flow-next"><span>שלב 1 · מעצבים את ההזמנה</span></div>'+invitations().replace('נועה ואיתי',esc(active().name)).replace('18.06.2027',esc(active().date.split('-').reverse().join('.')))+'<div class="invitation-next"><button class="primary" data-go="guests">המשך לרשימת המוזמנים ←</button></div>';}
function eventGuestView(){const list=eventGuestLists[activeEvent]||[];const top=`<div class="flow-next"><span>שלב 2 · רשימת המוזמנים</span></div><div class="guest-actions"><button class="primary" id="add-event-guest">＋ הוספת מוזמן</button><button class="secondary" data-demo="חיבור אנשי קשר יהיה זמין בהמשך. לא ניגשנו לאנשי הקשר שלך.">חיבור אנשי קשר</button><button class="secondary" data-demo="תצוגת שליחה לכולם בלבד. לא נשלחה הודעת וואטסאפ לאיש.">שליחת הזמנה לכולם</button></div>`;const next='<div class="invitation-next"><button type="button" class="primary" data-go="seating">המשך לסידורי ההושבה ←</button></div>'+paidSeatingOffer();if(activeEvent==='wedding')return top+guestsView()+next;return top+`<section class="panel"><div class="panel-title"><h2>רשימת המוזמנים</h2><small>${list.length} רשומות באירוע</small></div>${list.map(g=>`<div class="history-row"><div><bdi>${esc(g.name)}</bdi><small>${g.count} משתתפים · ${esc(g.side||'ללא ציון צד')}</small></div><select data-event-rsvp="${g.id}" aria-label="אישור הגעה של ${esc(g.name)}">${rsvpStatuses.map(status=>`<option ${g.status===status?'selected':''}>${status}</option>`).join('')}</select></div>`).join('')||'<div class="empty">הרשימה שלכם מתחילה כאן. הוסיפו את המוזמן הראשון או בחרו בחיבור אנשי קשר.</div>'}<p class="muted">אבטיפוס מקומי. אנשי קשר, שליחה ואישורי הגעה חיצוניים אינם מחוברים עדיין.</p></section>`+next;}
function eventSeatingView(){if(customerSeatingReady()&&!demoVenueMembership[invitationLocation().venueId])return customerSeatingReference()+seating();if(!canAccessSeating())return paidSeatingOffer()+'<section class="panel"><h2>סידורי הושבה דורשים מנוי אולם או מסלול אישי</h2><button class="secondary" data-go="invitations">לפרטי האולם בהזמנה</button></section>';const state=seatingState();let body='<p class="design-note">בחרו סקיצה סטנדרטית או סקיצה מיוחדת כדי להמשיך.</p>';if(state.layoutMode==='standard')body=state.seatingStarted?seating():standardLayoutPreview();if(state.layoutMode==='special')body=specialLayoutPanel()+(state.specialUrl?(state.seatingStarted?seating():specialLayoutSetup()):'<p class="design-note">לאחר אישור האולם והעלאת הסקיצה תוכלו להגדיר שולחנות ולהתחיל לשבץ.</p>');return seatingVenuePicker()+layoutModePicker()+body;}
const guestEntryDialog=document.createElement('dialog');document.body.appendChild(guestEntryDialog);
document.addEventListener('click',e=>{if(!e.target.closest('#add-event-guest'))return;guestEntryDialog.innerHTML='<div class="dialog-top"><h2>הוספת מוזמן לאירוע</h2><button class="close" aria-label="סגירה">×</button></div><form id="event-guest-entry"><label>שם אורח / משפחה<input name="name" required maxlength="90"></label><label>מספר משתתפים<input type="number" name="count" min="1" max="50" value="1" required></label><label>צד (לא חובה)<input name="side" maxlength="60" placeholder="למשל, המשפחה שלי"></label><button type="submit" class="primary">הוספה לרשימה</button></form>';guestEntryDialog.showModal();});
document.addEventListener('submit',e=>{if(e.target.id!=='event-guest-entry')return;e.preventDefault();const f=new FormData(e.target),name=f.get('name').trim();if(!name)return;const g={id:Date.now(),name,count:Number(f.get('count')),side:f.get('side').trim(),group:'נוסף ידנית',status:'ממתינים',table:null};if(activeEvent==='wedding')guests.push(g);else(eventGuestLists[activeEvent]??=[]).push(g);guestEntryDialog.close();render();toast('המוזמן נוסף לאירוע');});
const financeDialog=document.createElement('dialog');financeDialog.id='finance-dialog';document.body.appendChild(financeDialog);
function expensesView(){const records=expenseRecords.filter(r=>r.event===activeEvent),total=records.reduce((n,r)=>n+r.total,0),p=records.reduce((n,r)=>n+paid(r),0);return `<div class="toolbar"><div><h2>הוצאות ותשלומים</h2><p>הספקים, העלויות וכל מה שכבר שולם באירוע ${esc(active().name)}.</p></div><button class="primary" id="add-supplier">＋ הוצאה או בעל מקצוע</button></div><div class="metrics finance-metrics">${metric('עלות כוללת שסוכמה',nis(total),'כל ההוצאות באירוע','₪')}${metric('שולם עד עכשיו',nis(p),'לפי התשלומים שנרשמו','✓')}${metric('נותר לתשלום',nis(total-p),'יתרה מול הספקים','◷')}</div><div class="table-wrap"><table><thead><tr><th>ספק / בעל מקצוע</th><th>עבור מה</th><th>עלות שסוכמה</th><th>שולם</th><th>יתרה</th><th></th></tr></thead><tbody>${records.map(r=>`<tr><td>${esc(r.supplier)}</td><td>${esc(r.category)}</td><td><bdi>${nis(r.total)}</bdi></td><td><bdi>${nis(paid(r))}</bdi></td><td><bdi>${nis(r.total-paid(r))}</bdi></td><td><button class="text-button" data-finance="${r.id}">פירוט ותשלומים</button></td></tr>`).join('')||'<tr><td colspan="6">אין עדיין הוצאות לאירוע הזה. הוסיפו ספק או הוצאה כדי להתחיל.</td></tr>'}</tbody></table></div><p class="muted">תיעוד בלבד. אין כאן העברת כסף או סליקה. הנתונים נשמרים עד לרענון המסך.</p>`;}
function showSupplier(id){const r=expenseRecords.find(r=>r.id===id);financeDialog.innerHTML=`<div class="dialog-top"><div><h2>${esc(r.supplier)}</h2><small>${esc(r.category)} · עלות שסוכמה <bdi>${nis(r.total)}</bdi></small></div><button class="close" aria-label="סגירה">×</button></div><h3>תשלומים שבוצעו</h3>${r.payments.map(p=>`<div class="history-row"><span><bdi>${date(p.date)}</bdi></span><strong><bdi>${nis(p.amount)}</bdi></strong></div>`).join('')||'<p class="muted">עדיין לא נרשמו תשלומים.</p>'}<p class="design-note">נותר לתשלום: <bdi>${nis(r.total-paid(r))}</bdi></p>${paid(r)<r.total?`<form id="payment-form" data-id="${r.id}"><h3>רישום תשלום</h3><div class="form-grid" style="margin-top:17px"><label>סכום בש״ח<input type="number" name="amount" min="0.01" max="${r.total-paid(r)}" step="0.01" required></label><label>תאריך<input type="date" name="date" required></label></div><button type="submit" class="primary">רישום תשלום</button></form>`:'<p class="received">ההוצאה שולמה במלואה.</p>'}`;if(!financeDialog.open)financeDialog.showModal();}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.openEvent){activeEvent=b.dataset.openEvent;navigate('overview');}if(b.dataset.finance)showSupplier(Number(b.dataset.finance));if(b.id==='add-supplier'){financeDialog.innerHTML=`<div class="dialog-top"><h2>הוצאה או בעל מקצוע</h2><button class="close" aria-label="סגירה">×</button></div><form id="supplier-form"><label>שם הספק / ההוצאה<input name="supplier" required maxlength="90" placeholder="למשל, צלם האירוע"></label><label>עבור מה<input name="category" required maxlength="90" placeholder="למשל, צילום סטילס ווידאו"></label><label>עלות שסוכמה בש״ח<input type="number" min="0.01" max="100000000" step="0.01" name="total" required></label><button type="submit" class="primary">שמירת הוצאה</button></form>`;financeDialog.showModal();}});
document.addEventListener('submit',e=>{if(!['new-personal-event','supplier-form','payment-form'].includes(e.target.id))return;e.preventDefault();const f=new FormData(e.target);if(e.target.id==='new-personal-event'){const name=f.get('name').trim();if(!name)return;const event={id:crypto.randomUUID(),name,type:f.get('type'),date:f.get('date'),past:f.get('date')<'2026-10-29'};myEvents.push(event);activeEvent=event.id;navigate('overview');toast('האירוע נוסף לתצוגת הדוגמה');}if(e.target.id==='supplier-form'){if(!f.get('supplier').trim()||!f.get('category').trim())return;expenseRecords.push({id:expenseId++,event:activeEvent,supplier:f.get('supplier').trim(),category:f.get('category').trim(),total:Math.round(Number(f.get('total'))*100)/100,payments:[]});financeDialog.close();render();toast('ההוצאה נוספה לאירוע');}if(e.target.id==='payment-form'){const r=expenseRecords.find(r=>r.id===Number(e.target.dataset.id)),amount=Math.round(Number(f.get('amount'))*100)/100;if(!(amount>0)||amount>Math.round((r.total-paid(r))*100)/100)return;r.payments.push({amount,date:f.get('date')});render();showSupplier(r.id);toast('התשלום נרשם');}});


const providerData=[{id:1,name:'סטודיו אור',category:'צילום',regions:['מרכז','שרון'],events:['חתונה','בר/בת מצווה','ברית/בריתה'],note:'צילום סטילס ווידאו לאירועים משפחתיים',icon:'◉'},{id:2,name:'רותם על העמדה',category:'מוזיקה ותקליטנים',regions:['מרכז','דרום'],events:['חתונה','בר/בת מצווה','יום הולדת'],note:'מוזיקה שמחברת בין הדורות',icon:'♫'},{id:3,name:'פרחים במדבר',category:'עיצוב ופרחים',regions:['דרום','שפלה'],events:['חתונה','בר/בת מצווה','ברית/בריתה','יום הולדת'],note:'עיצוב שולחנות, חופות ומרחבים חגיגיים',icon:'✿'},{id:4,name:'שולחן פתוח',category:'קייטרינג',regions:['צפון','חיפה'],events:['חתונה','בר/בת מצווה','ברית/בריתה','יום הולדת'],note:'תפריטים מותאמים לחגיגה שלכם',icon:'♧'},{id:5,name:'מתוק מהלב',category:'עוגות וקינוחים',regions:['ירושלים','מרכז'],events:['חתונה','בר/בת מצווה','ברית/בריתה','יום הולדת'],note:'עוגות מעוצבות ושולחנות קינוחים',icon:'◇'},{id:6,name:'קסם קטן',category:'אטרקציות והפעלות',regions:['שרון','מרכז','צפון'],events:['בר/בת מצווה','יום הולדת'],note:'פעילויות וחוויות לאורחים הצעירים',icon:'✧'},{id:7,name:'רגע של טקס',category:'הנחיה וטקסים',regions:['ירושלים','מרכז','שפלה'],events:['חתונה','בר/בת מצווה','ברית/בריתה'],note:'ליווי והנחיה לרגעים המשמעותיים',icon:'◈'},{id:8,name:'סהרה אירועים',category:'אולמות וגני אירועים',regions:['שרון'],events:['חתונה','בר/בת מצווה','ברית/בריתה'],note:'גן ואולם במרחב טבעי',icon:'⌂'}];
const providerVenues=[{id:'sahara',name:'סהרה · עמק חפר',region:'שרון'},{id:'demo-center',name:'אולם לדוגמה · מרכז',region:'מרכז'},{id:'demo-north',name:'אולם לדוגמה · צפון',region:'צפון'}];let providerVenue='all';
let providerRegion='all',providerCategory='all',providerEvent='all';const localRatings={};
function providerFilter(id,title,values,selected){return '<label>'+title+'<select id="'+id+'"><option value="all">הכול</option>'+values.map(v=>'<option '+(selected===v?'selected':'')+'>'+esc(v)+'</option>').join('')+'</select></label>';}
function providersView(){const list=providerData.filter(p=>(providerRegion==='all'||p.regions.includes(providerRegion))&&(providerCategory==='all'||p.category===providerCategory)&&(providerEvent==='all'||p.events.includes(providerEvent)));return '<div class="toolbar"><div><h2>האנשים שמאחורי האירוע</h2><p>מוצאים בעלי מקצוע לפי מה שצריך ולפי האזור שבו הם עובדים.</p></div></div><div class="provider-disclosure">מאגר לדוגמה · במוצר המתוכנן בעלי המקצוע ישלמו על הופעה במאגר. תשלום על פרסום אינו דירוג לקוחות.</div><div class="provider-venue-picker"><label for="provider-venue">באיזה אולם חוגגים?</label><select id="provider-venue"><option value="all">ללא בחירת אולם</option>'+providerVenues.map(v=>'<option value="'+v.id+'" '+(providerVenue===v.id?'selected':'')+'>'+esc(v.name)+'</option>').join('')+'</select><p class="muted" role="status">'+(providerVenue==='all'?'בחרו אולם כדי לסנן אוטומטית לפי אזור השירות שלו.':'מציגים בעלי מקצוע שנותנים שירות באזור '+esc(providerVenues.find(v=>v.id===providerVenue).region)+'. ההתאמה לפי אזור בלבד, ולא לפי הסכם עם האולם.')+'</p></div><div class="provider-filters">'+providerFilter('provider-region','אזור שירות',['צפון','חיפה','שרון','מרכז','שפלה','ירושלים','דרום'],providerRegion)+providerFilter('provider-category','סוג בעל מקצוע',[...new Set(providerData.map(p=>p.category))],providerCategory)+providerFilter('provider-event','סוג האירוע',['חתונה','בר/בת מצווה','ברית/בריתה','יום הולדת'],providerEvent)+'</div><p class="muted">'+list.length+' בעלי מקצוע מתאימים · שמות ופרטים להמחשת העיצוב בלבד</p><div class="provider-grid">'+list.map(p=>'<article class="provider-card"><div class="provider-top"><span class="provider-icon">'+p.icon+'</span><span class="provider-ad">כרטיס פרסום · דוגמה</span></div><small>'+p.category+'</small><h3>'+p.name+'</h3><p>'+p.note+'</p><div class="provider-regions"><b>אזורי שירות</b><span>'+p.regions.join(' · ')+'</span></div><small>מתאים ל: '+p.events.join(', ')+'</small><div class="provider-rating"><span>אין עדיין דירוגי לקוחות</span><fieldset><legend>הדירוג שלך בכוכבים בלבד</legend><div class="star-options">'+[1,2,3,4,5].map(n=>'<label title="'+n+' כוכבים"><input type="radio" name="provider-rating-'+p.id+'" data-provider-rating="'+p.id+'" value="'+n+'" '+(localRatings[p.id]===n?'checked':'')+'><span class="'+(n<=(localRatings[p.id]||0)?'filled':'')+'" aria-hidden="true">★</span><span class="sr-only">'+n+' כוכבים</span></label>').join('')+'</div></fieldset><small>'+(localRatings[p.id]?'בחרת '+localRatings[p.id]+' מתוך 5 · דירוג הדגמה בלבד':'ללא טקסט חופשי. הבחירה מקומית בלבד.')+'</small></div></article>').join('')+'</div>'+(list.length?'':'<section class="panel"><h3>לא נמצאו בעלי מקצוע בשילוב שבחרת</h3><p class="muted">אפשר לשנות את אזור השירות, התחום או סוג האירוע.</p></section>')+'<p class="muted">בעתיד דירוג לקוח יחובר לשירות שקיבל בפועל. כרגע אין אימות לקוחות, שמירה מתמשכת או גביית תשלום.</p>';}
document.addEventListener('change',e=>{if(e.target.id==='provider-venue'){providerVenue=e.target.value;providerRegion=providerVenues.find(v=>v.id===providerVenue)?.region||'all';render();}if(e.target.id==='provider-region'){providerRegion=e.target.value;providerVenue='all';render();}if(e.target.id==='provider-category'){providerCategory=e.target.value;render();}if(e.target.id==='provider-event'){providerEvent=e.target.value;render();}if(e.target.dataset.providerRating){localRatings[e.target.dataset.providerRating]=Number(e.target.value);render();toast('הדירוג עודכן בתצוגת הדוגמה בלבד');}});






document.addEventListener('input',e=>{if(e.target.id!=='invitation-message')return;invitationMessages[activeEvent]=e.target.value;$('#invitation-message-preview').textContent=e.target.value;});
document.addEventListener('click',e=>{if(!e.target.closest('#reset-invitation-message'))return;delete invitationMessages[activeEvent];$('#invitation-message').value=defaultInvitationMessage;$('#invitation-message-preview').textContent=defaultInvitationMessage;});

document.addEventListener('input',e=>{if(e.target.id!=='invitation-heading')return;invitationHeadings[activeEvent]=e.target.value;$('#invitation-heading-preview').textContent=e.target.value;});
document.addEventListener('click',e=>{if(!e.target.closest('#reset-invitation-heading'))return;delete invitationHeadings[activeEvent];$('#invitation-heading').value=defaultInvitationHeading;$('#invitation-heading-preview').textContent=defaultInvitationHeading;});

const venuePhotos={},venueLayouts={},venueSpaces={};let venueRegion='all';
function venuesView(){const venues=providerVenues.filter(v=>venueRegion==='all'||v.region===venueRegion);return '<div class="toolbar"><div><h2>המקום שבו הכול מתחיל</h2><p>אולמות אירועים לרגעים המיוחדים שלכם.</p></div></div><div class="provider-disclosure">מאגר אולמות להמחשה בלבד · המידע אינו רשימת אולמות מאומתת. אין כאן בדיקת זמינות או הזמנות.</div><div class="venue-directory-filter">'+providerFilter('venue-region','אזור בארץ',[...new Set(providerVenues.map(v=>v.region))],venueRegion)+'</div><p class="muted" role="status">'+venues.length+' אולמות בתצוגה</p><div class="venue-directory">'+venues.map(v=>'<article class="venue-directory-card">'+(venuePhotos[v.id]?'<img class="venue-photo" src="'+esc(venuePhotos[v.id])+'" alt="תמונה של '+esc(v.name)+'">':'<div class="venue-illustration" aria-hidden="true"><span class="venue-arch"></span><span class="venue-illustration-label">BESTEVENT</span></div>')+'<div class="venue-directory-details"><span class="provider-ad">אולם לדוגמה</span><h3>'+esc(v.name)+'</h3><p>אזור '+esc(v.region)+'</p><label class="venue-photo-upload">'+(venuePhotos[v.id]?'החלפת תמונת האולם':'הוספת תמונת האולם')+'<input type="file" accept="image/jpeg,image/png,image/webp" data-venue-photo="'+v.id+'"></label><small>התמונה נשמרת בתצוגה עד לרענון בלבד.</small>'+venueLayoutCard(v)+'<button type="button" class="secondary" data-venue-providers="'+v.id+'">בעלי מקצוע באזור האולם ←</button></div></article>').join('')+'</div>';}
document.addEventListener('change',e=>{if(e.target.id==='venue-region'){venueRegion=e.target.value;render();}});
document.addEventListener('click',e=>{const button=e.target.closest('[data-venue-providers]');if(!button)return;const venue=providerVenues.find(v=>v.id===button.dataset.venueProviders);if(!venue)return;providerVenue=venue.id;providerRegion=venue.region;providerCategory='all';providerEvent='all';navigate('providers');});

document.addEventListener('change',e=>{const id=e.target.dataset.venuePhoto;if(!id)return;const file=e.target.files?.[0];if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>10*1024*1024){toast('בחרו תמונת JPG, PNG או WebP עד 10 מגה');e.target.value='';return;}const url=URL.createObjectURL(file);const image=new Image();image.onload=()=>{if(venuePhotos[id])URL.revokeObjectURL(venuePhotos[id]);venuePhotos[id]=url;render();toast('תמונת האולם נוספה');};image.onerror=()=>{URL.revokeObjectURL(url);toast('לא ניתן לפתוח את התמונה. נסו קובץ אחר.');};image.src=url;});

function venueLayoutCard(v){const large=Object.values(standardSeatingCapacities({venueId:v.id,space:'large'})).reduce((sum,n)=>sum+n,0),small=Object.values(standardSeatingCapacities({venueId:v.id,space:'small'})).reduce((sum,n)=>sum+n,0);return '<section class="venue-capacity-summary"><h4>החללים באולם</h4><div><span>אולם גדול</span><strong>עד '+large+' אורחים</strong></div><div><span>אולם קטן</span><strong>עד '+small+' אורחים</strong></div><p class="muted">אפשרויות סידור: סקיצה סטנדרטית או סידור מיוחד בתיאום עם האולם.</p><small>החללים והקיבולות להדגמה בלבד ואינם מידע מאומת על האולם.</small></section>';}
document.addEventListener('click',e=>{const b=e.target.closest('[data-venue-space]');if(!b)return;venueSpaces[b.dataset.venueSpace]=b.dataset.space;render();});

// Local interaction prototype. These approvals are not server authorization.
const eventSeatingVenues={wedding:{venueId:'sahara',space:'small'}};
const demoVenueMembership={sahara:true,'demo-center':true,'demo-north':false};
const demoLayoutApprovals={};
function seatingState(){const selectedVenue=invitationLocation().venueId;const venueId=demoVenueMembership[selectedVenue]?selectedVenue:customerSeatingReady()?'paid-custom':'';let state=eventSeatingVenues[activeEvent];if(!state||state.venueId!==venueId){if(state?.specialUrl)URL.revokeObjectURL(state.specialUrl);state=eventSeatingVenues[activeEvent]={venueId,space:venueId==='paid-custom'?'custom':state?.space==='small'?'small':'large'};delete demoLayoutApprovals[activeEvent];autoSeatUndo=null;autoSeatMessage='';}return state;}
function seatingGuests(){return activeEvent==='wedding'?guests:(eventGuestLists[activeEvent]||[]);}
function seatingCapacities(){const state=seatingState();if(state.layoutMode==='special'&&state.customCapacities)return state.customCapacities;if(customerSeatingReady()&&!demoVenueMembership[invitationLocation().venueId])return customerSeatingPass().capacities;return standardSeatingCapacities(seatingState());}
function standardSeatingCapacities(state){if(state.venueId==='sahara'&&state.space==='small')return {1:10,2:10,3:12,4:10,5:12,6:10};const count=state.space==='small'?6:12;return Object.fromEntries(Array.from({length:count},(_,i)=>[i+1,state.venueId==='demo-center'?12:10]));}
function seatingVenuePicker(){const state=seatingState();return `<section class="panel seating-venue-picker"><div><h2>האולם והסקיצה שלכם</h2><p class="muted">רשימת מנויים להדגמה בלבד · אין כרגע מערכת מנויים מחוברת.</p></div><div class="seating-venue-fields"><label>האולם שנבחר בהזמנה<input id="seating-venue" readonly value="${esc(invitationLocationDetails().name)}" aria-describedby="seating-venue-origin"></label><label>חלל<select id="seating-space" ${!state.venueId?'disabled':''}><option value="large" ${state.space==='large'?'selected':''}>האולם הגדול</option><option value="small" ${state.space==='small'?'selected':''}>האולם הקטן</option></select></label></div><p id="seating-venue-origin" class="muted">האולם מתמלא אוטומטית מעיצוב ההזמנה. כאן בוחרים רק את החלל.</p><button type="button" class="text-button" data-go="invitations">שינוי האולם בעיצוב ההזמנה</button>${state.venueId?`<p class="muted">נטענה סקיצת הדגמה סטנדרטית · ${Object.keys(seatingCapacities()).length} שולחנות. הסקיצה והקיבולת אינן מידע מאומת על האולם.</p>`:''}</section>`;}
function approvalScope(eventId,state){return eventId+':'+state.venueId+':'+state.space;}
function specialLayoutPanel(){const state=seatingState(),approval=demoLayoutApprovals[activeEvent];const ready=approval?.scope===approvalScope(activeEvent,state)&&approval.verified&&!approval.used&&Date.now()<approval.expires;return `<details id="special-layout-panel" class="panel special-layout-panel" open><summary>סקיצה מיוחדת לאירוע · אישור והעלאה</summary><p class="muted">במוצר המלא האולם יאשר העלאה עבור האירוע והחלל שנבחרו באמצעות קוד חד־פעמי. לפני שימוש בסקיצה, האולם יצטרך לאשר גם את התמונה עצמה.</p><div class="approval-demo-note">הדגמה מקומית בלבד: הקוד כאן אינו אישור אמיתי של אולם ואינו מנגנון אבטחה.</div><details id="demo-approval-controls" class="demo-approval-controls"><summary>התנסות בתהליך אישור האולם</summary><p class="muted">הכפתור הבא מדמה אישור מצד האולם. הוא לא שולח הודעה ולא בודק מנוי אמיתי.</p><button type="button" class="secondary" id="demo-issue-layout-code">הדמיית אישור האולם והפקת קוד</button>${approval&&!approval.used&&!approval.verified?`<p class="muted">קוד הדגמה: <bdi>${approval.code}</bdi> · תקף ל־10 דקות, לאירוע ולחלל שנבחרו בלבד.</p>`:''}</details><form id="verify-layout-code" class="layout-code-form"><label for="layout-code">קוד חד־פעמי מהאולם</label><div><input id="layout-code" name="code" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" minlength="6" required autocomplete="one-time-code" placeholder="6 ספרות"><button type="submit" class="secondary">בדיקת קוד</button></div></form><p id="layout-approval-status" class="muted" role="status">${ready?'אישור הדגמה התקבל. ניתן לבחור תמונה אחת להעלאה.':approval?.used?'אישור ההדגמה נוצל. להחלפת סקיצה נדרש אישור חדש.':'העלאה נעולה עד לאישור. אין בקשה שנשלחה לאולם.'}</p><label class="venue-photo-upload">העלאת סקיצה מיוחדת<input id="event-special-layout" type="file" accept="image/jpeg,image/png,image/webp" ${ready?'':'disabled'}></label><small>JPG, PNG או WebP עד 10 מגה. הקובץ נשאר בדפדפן עד לרענון.</small>${state.specialUrl?`<div class="event-special-preview"><h3>הסקיצה המיוחדת שלכם</h3><a href="${esc(state.specialUrl)}" target="_blank" rel="noopener"><img src="${esc(state.specialUrl)}" alt="סקיצה מיוחדת לאירוע ${esc(active().name)}"><span>פתיחה בגודל מלא ↗</span></a><p class="muted">מגדירים את השולחנות לפי הסקיצה הזו לפני השיבוץ. התמונה אינה מזוהה אוטומטית; מיקומי השולחנות ברשת הם סכמטיים.</p><button type="button" class="text-button" id="remove-special-layout">הסרת תמונת הסקיצה המיוחדת</button></div>`:''}</details>`;}
function updateSeatingVenue(venueId,space){if(venueId&&!demoVenueMembership[venueId])return false;if(!['large','small'].includes(space))return false;const previous=seatingState();const candidate={venueId,space};eventSeatingVenues[activeEvent]=candidate;const limits=standardSeatingCapacities(candidate);const invalid=seatingGuests().some(g=>g.table&&(!venueId||!limits[g.table]||occupancy(g.table)>limits[g.table]));if(invalid){eventSeatingVenues[activeEvent]=previous;toast('הסקיצה שנבחרה אינה מתאימה לשיבוצים הקיימים. פנו תחילה את השולחנות הרלוונטיים.');render();return false;}if(previous.specialUrl)URL.revokeObjectURL(previous.specialUrl);delete demoLayoutApprovals[activeEvent];autoSeatUndo=null;autoSeatMessage='';selectedTable=1;if(venueId)invitationLocation().venueId=venueId;render();return true;}
function issueDemoLayoutCode(){const state=seatingState();if(!canAccessSeating()||!demoVenueMembership[state.venueId])return null;const random=new Uint32Array(1);crypto.getRandomValues(random);const code=String(100000+random[0]%900000);demoLayoutApprovals[activeEvent]={scope:approvalScope(activeEvent,state),code,expires:Date.now()+10*60*1000,attempts:0,verified:false,used:false};return code;}
function verifyDemoLayoutCode(code){const state=seatingState(),a=demoLayoutApprovals[activeEvent];if(!canAccessSeating()||!demoVenueMembership[state.venueId]||!a||a.scope!==approvalScope(activeEvent,state))return 'לא נמצא אישור הדגמה לאירוע ולחלל האלה.';if(a.used||a.verified)return 'הקוד כבר נוצל. להעלאה נוספת נדרש אישור חדש.';if(Date.now()>=a.expires)return 'תוקף הקוד פג. נדרש אישור חדש.';if(a.attempts>=5)return 'הגעתם למגבלת הניסיונות. נדרש אישור חדש.';a.attempts++;if(code.trim()!==a.code)return 'הקוד שגוי. נסו שוב.';a.verified=true;return '';}
document.addEventListener('change',e=>{if(e.target.id==='seating-space')updateSeatingVenue(seatingState().venueId,e.target.value);});
document.addEventListener('click',e=>{if(e.target.closest('#demo-issue-layout-code')){issueDemoLayoutCode();render();toast('נוצר קוד להתנסות בלבד. לא נשלחה הודעה לאולם.');}if(e.target.closest('#remove-special-layout')){const state=seatingState();if(state.specialUrl)URL.revokeObjectURL(state.specialUrl);delete state.specialUrl;delete state.customCapacities;state.seatingStarted=false;render();}});
document.addEventListener('submit',e=>{if(e.target.id!=='verify-layout-code')return;e.preventDefault();const error=verifyDemoLayoutCode(new FormData(e.target).get('code'));if(error){$('#layout-approval-status').textContent=error;return;}render();toast('קוד ההדגמה אומת. אפשר להעלות תמונה אחת.');});
document.addEventListener('change',e=>{if(e.target.id!=='event-special-layout')return;const eventId=activeEvent,state=seatingState(),a=demoLayoutApprovals[eventId],file=e.target.files?.[0];if(!file)return;const authorized=()=>canAccessSeating()&&demoVenueMembership[state.venueId]&&eventSeatingVenues[eventId]===state&&demoLayoutApprovals[eventId]===a&&a?.scope===approvalScope(eventId,state)&&a.verified&&!a.used&&Date.now()<a.expires;if(!authorized()){toast('נדרש אישור חדש עבור האולם והחלל שנבחרו');return;}if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>10*1024*1024){toast('בחרו תמונת JPG, PNG או WebP עד 10 מגה');return;}a.used=true;const url=URL.createObjectURL(file),image=new Image();image.onload=()=>{if(demoLayoutApprovals[eventId]!==a||eventSeatingVenues[eventId]!==state||Date.now()>=a.expires){URL.revokeObjectURL(url);toast('האישור או בחירת האולם השתנו. נדרש אישור חדש.');return;}if(state.specialUrl)URL.revokeObjectURL(state.specialUrl);state.specialUrl=url;state.seatingStarted=false;delete state.customCapacities;if(activeEvent===eventId)render();toast('סקיצת ההדגמה צורפה לאירוע');};image.onerror=()=>{URL.revokeObjectURL(url);if(demoLayoutApprovals[eventId]===a)a.used=false;toast('התמונה אינה תקינה. בחרו תמונה אחרת.');};image.src=url;});

document.addEventListener('change',e=>{if(!e.target.dataset.eventRsvp)return;const g=seatingGuests().find(g=>String(g.id)===e.target.dataset.eventRsvp);if(!g||!rsvpStatuses.includes(e.target.value))return;g.status=e.target.value;if(g.status!=='אישרו')g.table=null;autoSeatUndo=null;autoSeatMessage='';render();});

function invitationLocation(){return invitationLocations[activeEvent]??={venueId:activeEvent==='wedding'?'sahara':'manual',manualName:'',manualAddress:''};}
function invitationLocationDetails(){const location=invitationLocation(),venue=providerVenues.find(v=>v.id===location.venueId&&demoVenueMembership[v.id]);return venue?{name:venue.name,address:invitationVenueAddresses[venue.id]||'כתובת מדויקת טרם הוזנה'}:{name:location.manualName,address:location.manualAddress};}
function invitationVenueEditor(){const location=invitationLocation(),details=invitationLocationDetails(),manual=location.venueId==='manual';return '<fieldset class="invitation-venue-editor"><legend>איפה חוגגים?</legend><label for="invitation-venue">אולמות שעובדים איתנו</label><select id="invitation-venue">'+providerVenues.filter(v=>demoVenueMembership[v.id]).map(v=>'<option value="'+v.id+'" '+(location.venueId===v.id?'selected':'')+'>'+esc(v.name)+' · הדגמה</option>').join('')+'<option value="manual" '+(manual?'selected':'')+'>האולם לא ברשימה — הזנה ידנית</option></select><label for="invitation-location-name">שם האולם / המקום</label><input id="invitation-location-name" maxlength="120" value="'+esc(details.name)+'" '+(manual?'':'readonly')+' placeholder="שם המקום"><label for="invitation-location-address">כתובת האירוע</label><input id="invitation-location-address" maxlength="240" value="'+esc(details.address)+'" '+(manual?'':'readonly')+' placeholder="רחוב, מספר ויישוב"><p class="muted">'+(manual?'מלאו את שם המקום והכתובת. הפרטים מתעדכנים מיד בהזמנה.':'הפרטים מולאו מרשומת אולם ההדגמה. הכתובות אינן מאומתות; לתיקון כתובת בחרו הזנה ידנית.')+'</p></fieldset>';}
document.addEventListener('change',e=>{if(e.target.id!=='invitation-venue')return;const id=e.target.value;if(id!=='manual'&&!providerVenues.some(v=>v.id===id&&demoVenueMembership[v.id]))return;if(id!=='manual'&&!updateSeatingVenue(id,seatingState().space))return;invitationLocation().venueId=id;if(id==='manual'){delete demoLayoutApprovals[activeEvent];autoSeatUndo=null;autoSeatMessage='';}render();});
document.addEventListener('input',e=>{if(!['invitation-location-name','invitation-location-address'].includes(e.target.id))return;const location=invitationLocation();if(location.venueId!=='manual')return;location[e.target.id==='invitation-location-name'?'manualName':'manualAddress']=e.target.value;const details=invitationLocationDetails();$('#invitation-venue-name-preview').textContent=details.name;$('#invitation-venue-address-preview').textContent=details.address;});
function canAccessSeating(){const venueId=invitationLocation().venueId;return Boolean((venueId!=='manual'&&demoVenueMembership[venueId])||customerSeatingReady());}
// Customer-paid access is a local checkout simulation, never proof of payment.
const customerSeatingPasses={};
function customerSeatingScope(){const location=invitationLocation(),details=invitationLocationDetails();return JSON.stringify([activeEvent,location.venueId,details.name,details.address]);}
function customerSeatingPass(){const pass=customerSeatingPasses[activeEvent];return pass?.scope===customerSeatingScope()?pass:null;}
function customerSeatingReady(){const pass=customerSeatingPass();return Boolean(pass?.demoPaid&&pass.imageUrl&&pass.ready&&pass.capacities);}
function paidSeatingOffer(){if(demoVenueMembership[invitationLocation().venueId])return '';return '<div class="customer-seating-offer"><div><h3>האולם לא מנוי? אפשר במסלול אישי</h3><p>תשלום חד־פעמי לאירוע, העלאת סקיצה והגדרת שולחנות לפני תחילת השיבוץ.</p></div><button type="button" class="secondary" data-go="seatingPurchase">'+(customerSeatingReady()?'ניהול הסקיצה והמסלול האישי':'למסלול הושבה אישי')+'</button></div>';}
function paidSeatingView(){const pass=customerSeatingPass(),details=invitationLocationDetails();return '<section class="panel customer-seating-setup"><h2>סידורי הושבה במסלול אישי</h2><p class="muted">עבור '+esc(active().name)+' · '+esc(details.name||'יש להזין את שם האולם בהזמנה')+'</p><div class="approval-demo-note">הדגמת תהליך בלבד. אין כאן סליקה או חיוב, ומחיר המסלול עדיין לא נקבע. ההרשאה והסקיצה נשמרות עד לרענון.</div><ol class="customer-seating-steps"><li><h3>תשלום חד־פעמי לאירוע</h3><p class="muted">במוצר המלא התשלום יאומת בשרת. התנסות זו אינה מבקשת פרטי כרטיס.</p><button type="button" class="secondary" id="demo-customer-payment" '+(pass?.demoPaid?'disabled':'')+'>'+(pass?.demoPaid?'הדמיית התשלום הושלמה':'הדמיית תשלום — ללא חיוב')+'</button></li><li><h3>העלאת סקיצה של האולם והסידור המבוקש</h3><label class="venue-photo-upload">תמונת הסקיצה<input type="file" id="customer-seating-image" accept="image/jpeg,image/png,image/webp" '+(pass?.demoPaid?'':'disabled')+'></label><small>חובה להעלות תמונה תקינה לפני פתיחת ההושבה. JPG, PNG או WebP עד 10 מגה.</small>'+(pass?.imageUrl?'<img class="customer-plan-preview" src="'+esc(pass.imageUrl)+'" alt="הסקיצה שהועלתה לאירוע"><small>סקיצה הועלתה · ניתן להחליף תמונה</small>':'')+'</li><li><h3>הגדרת השולחנות לפי הסקיצה</h3><p class="muted">התמונה אינה מזוהה אוטומטית. הגדירו את מספר השולחנות והקיבולת הראשונית. ניתן לשנות קיבולת לכל שולחן לפני ההפעלה. מספרי השולחנות צריכים להתאים לסקיצה שלכם.</p><form id="customer-seating-plan"><div class="form-grid"><label>מספר שולחנות<input type="number" name="tables" min="1" max="60" step="1" value="'+(pass?.capacities?Object.keys(pass.capacities).length:12)+'" required '+(pass?.imageUrl?'':'disabled')+'></label><label>מקומות בכל שולחן<input type="number" name="seats" min="1" max="24" step="1" value="10" required '+(pass?.imageUrl?'':'disabled')+'></label></div><button class="secondary" type="submit" '+(pass?.imageUrl?'':'disabled')+'>הכנת רשימת שולחנות</button></form>'+(pass?.capacities?'<form id="activate-customer-seating"><div class="customer-table-capacities">'+Object.entries(pass.capacities).map(([table,capacity])=>'<label>שולחן '+table+'<input name="table-'+table+'" type="number" value="'+capacity+'" min="1" max="24" step="1" required></label>').join('')+'</div><p class="muted">השולחנות יוצגו ברשת לצד תמונת הסקיצה. המיקומים אינם מועתקים מהתמונה.</p><button type="submit" class="primary">אישור הסקיצה והמשך להושבה ←</button></form>':'')+'</li></ol><button type="button" class="text-button" data-go="invitations">עריכת שם האולם וכתובתו</button></section>';}
function customerSeatingReference(){const pass=customerSeatingPass();return '<section class="panel customer-seating-reference"><div class="panel-title"><h2>הסקיצה שלכם · מסלול אישי</h2><button type="button" class="secondary" data-go="seatingPurchase">עדכון סקיצה ושולחנות</button></div><a href="'+esc(pass.imageUrl)+'" target="_blank" rel="noopener"><img class="customer-plan-preview" src="'+esc(pass.imageUrl)+'" alt="סקיצת האולם והסידור לאירוע '+esc(active().name)+'"></a><p class="muted">העלאה אישית · הדגמת תשלום בלבד. השיבוץ ברשת השולחנות למטה, לפי המספרים והקיבולות שהגדרתם. מיקום השולחנות בתמונה לא זוהה אוטומטית.</p></section>';}
function customerPlanFits(capacities){const people=seatingGuests();return people.every(g=>!g.table||(capacities[g.table]&&people.filter(other=>other.table===g.table).reduce((sum,other)=>sum+other.count,0)<=capacities[g.table]));}
document.addEventListener('click',e=>{if(!e.target.closest('#demo-customer-payment'))return;if(demoVenueMembership[invitationLocation().venueId]){toast('האולם שנבחר כבר מופיע כמנוי הדגמה');return;}if(!invitationLocationDetails().name.trim()){toast('הזינו קודם את שם האולם בעיצוב ההזמנה');return;}const old=customerSeatingPasses[activeEvent];if(old?.imageUrl)URL.revokeObjectURL(old.imageUrl);customerSeatingPasses[activeEvent]={scope:customerSeatingScope(),demoPaid:true,ready:false};render();toast('התנסות בלבד: לא בוצע חיוב. העלו את סקיצת האולם להמשך.');});
document.addEventListener('change',e=>{if(e.target.id!=='customer-seating-image')return;const pass=customerSeatingPass(),eventId=activeEvent,file=e.target.files?.[0];if(!pass?.demoPaid||!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>10*1024*1024){toast('בחרו JPG, PNG או WebP עד 10 מגה');return;}const version=(pass.uploadVersion||0)+1;pass.uploadVersion=version;const url=URL.createObjectURL(file),image=new Image();image.onload=()=>{if(customerSeatingPasses[eventId]!==pass||pass.uploadVersion!==version){URL.revokeObjectURL(url);return;}if(pass.imageUrl)URL.revokeObjectURL(pass.imageUrl);pass.imageUrl=url;pass.ready=false;if(activeEvent===eventId)render();toast('הסקיצה צורפה. הגדירו שולחנות ואשרו לפני השיבוץ.');};image.onerror=()=>{URL.revokeObjectURL(url);toast('לא ניתן לפתוח את הסקיצה. בחרו תמונה תקינה.');};image.src=url;});
document.addEventListener('submit',e=>{if(!['customer-seating-plan','activate-customer-seating'].includes(e.target.id))return;e.preventDefault();const pass=customerSeatingPass();if(!pass?.demoPaid||!pass.imageUrl){toast('נדרשים תשלום הדגמה והעלאת סקיצה לפני ההמשך');return;}const form=new FormData(e.target);if(e.target.id==='customer-seating-plan'){const tables=Number(form.get('tables')),seats=Number(form.get('seats'));if(!Number.isInteger(tables)||tables<1||tables>60||!Number.isInteger(seats)||seats<1||seats>24)return;const capacities=Object.fromEntries(Array.from({length:tables},(_,i)=>[i+1,seats]));if(!customerPlanFits(capacities)){toast('ההגדרה החדשה אינה מתאימה לשיבוצים הקיימים. השיבוצים לא שונו.');return;}pass.capacities=capacities;pass.ready=false;render();return;}if(!pass.capacities)return;const capacities={};for(const table of Object.keys(pass.capacities)){const capacity=Number(form.get('table-'+table));if(!Number.isInteger(capacity)||capacity<1||capacity>24)return;capacities[table]=capacity;}if(!customerPlanFits(capacities)){toast('אין מספיק מקומות לשיבוצים הקיימים. השיבוצים לא שונו.');return;}pass.capacities=capacities;pass.ready=true;eventSeatingVenues[activeEvent]={venueId:'paid-custom',space:'custom'};autoSeatUndo=null;autoSeatMessage='';selectedTable=1;navigate('seating');});

function canAssignSeating(){if(!canAccessSeating())return false;if(customerSeatingReady()&&!demoVenueMembership[invitationLocation().venueId])return true;const state=seatingState();return Boolean(state.seatingStarted&&(state.layoutMode==='standard'||(state.layoutMode==='special'&&state.specialUrl&&state.customCapacities)));}
function layoutModePicker(){const mode=seatingState().layoutMode;return '<section class="layout-mode-picker"><h3>באיזו סקיצה משתמשים?</h3><div role="group" aria-label="בחירת סוג סקיצה"><button type="button" data-layout-mode="standard" aria-pressed="'+(mode==='standard')+'"><strong>סקיצה סטנדרטית</strong><span>סידור השולחנות הקבוע של החלל</span></button><button type="button" data-layout-mode="special" aria-pressed="'+(mode==='special')+'"><strong>סקיצה מיוחדת</strong><span>העלאת הסידור המבוקש והגדרת שולחנות</span></button></div></section>';}
function standardLayoutPreview(){const tables=Object.keys(standardSeatingCapacities(seatingState()));return '<section class="panel standard-layout-preview"><h3>הסקיצה הסטנדרטית · תצוגה מקדימה</h3><div class="venue-mini-plan"><div class="mini-plan-stage">במה וחופה</div><div class="mini-plan-tables">'+tables.map(table=>'<span>'+table+'</span>').join('')+'</div><div class="mini-plan-dance">רחבת ריקודים</div></div><p class="muted">סקיצת הדגמה · '+tables.length+' שולחנות. אחרי אישור הבחירה תיפתח רשימת המוזמנים לשיבוץ.</p><button type="button" class="primary" id="start-standard-seating">בחירת הסקיצה והתחלת שיבוץ ←</button></section>';}
function specialLayoutSetup(){const limits=seatingState().customCapacities;return '<form id="start-special-seating" class="panel special-layout-setup"><h3>הגדירו שולחנות לפי הסקיצה שהעליתם</h3><p class="muted">מספרו את השולחנות בסקיצה ברצף החל מ־1. הרשימה תיבנה לפי המספר והקיבולת שתזינו, ללא זיהוי אוטומטי מהתמונה.</p><div class="form-grid"><label>מספר שולחנות<input name="tables" type="number" min="1" max="60" step="1" value="'+(limits?Object.keys(limits).length:12)+'" required></label><label>מקומות בכל שולחן<input name="seats" type="number" min="1" max="24" step="1" value="'+(limits?Object.values(limits)[0]:10)+'" required></label></div><button type="submit" class="primary">אישור הסקיצה והתחלת שיבוץ ←</button></form>';}
document.addEventListener('click',e=>{const button=e.target.closest('[data-layout-mode]');if(button){if(!canAccessSeating()||!demoVenueMembership[invitationLocation().venueId])return;const state=seatingState();if(!['standard','special'].includes(button.dataset.layoutMode))return;if(state.layoutMode!==button.dataset.layoutMode){state.layoutMode=button.dataset.layoutMode;state.seatingStarted=false;autoSeatUndo=null;autoSeatMessage='';}render();}if(e.target.closest('#start-standard-seating')){if(!canAccessSeating())return;const state=seatingState();if(state.layoutMode!=='standard')return;if(!customerPlanFits(standardSeatingCapacities(state))){toast('הסקיצה הסטנדרטית אינה מתאימה לשיבוצים הקיימים. השיבוצים נשמרו.');return;}state.seatingStarted=true;selectedTable=1;render();}});
document.addEventListener('submit',e=>{if(e.target.id!=='start-special-seating')return;e.preventDefault();if(!canAccessSeating())return;const state=seatingState();if(state.layoutMode!=='special'||!state.specialUrl)return;const form=new FormData(e.target),tables=Number(form.get('tables')),seats=Number(form.get('seats'));if(!Number.isInteger(tables)||tables<1||tables>60||!Number.isInteger(seats)||seats<1||seats>24)return;const capacities=Object.fromEntries(Array.from({length:tables},(_,i)=>[i+1,seats]));if(!customerPlanFits(capacities)){toast('ההגדרה אינה מתאימה לשיבוצים הקיימים. בחרו מספר שולחנות וקיבולת מתאימים.');return;}state.customCapacities=capacities;state.seatingStarted=true;selectedTable=1;autoSeatUndo=null;autoSeatMessage='';render();});
navigate('home');
